namespace MudClient.Core.Equipment;

/// <summary>Body location of a random item generated by the game server.</summary>
public enum RandomItemCategory
{
    Weapon, Torso, Head, Face, Hands, Feet, Shield, Finger, Neck, Gem, Food, Shoulders, Ear, Legs, Arms, Wrist
}

/// <summary>A server command that operates on a confirmed group of items in one source list.</summary>
public sealed record ItemBulkGroup(string DisplayName, string CommandArgument, IReadOnlyList<string> ItemNames)
{
    public int Count => ItemNames.Count;
}

/// <summary>Unique noun signatures for random items, grouped by their server generator and wear
/// location. They were extracted from <c>random_items.c</c> and normalized to the ASCII spelling
/// used in client logs. Adjectives, materials and other random name modifiers are deliberately
/// excluded.</summary>
public static class RandomItemNameCatalog
{
    private static readonly IReadOnlyDictionary<RandomItemCategory, IReadOnlyList<string>> Catalog =
        new Dictionary<RandomItemCategory, IReadOnlyList<string>>
        {
