                "deggialryt", "diament", "dipsoid", "drakolid", "feerialyd", "furgasyd", "gagat",
                "garloopel", "granat", "gurthgyr", "gwiazda", "hematyt", "hiacynt", "jadeit", "jaspis",
                "kaintid", "kamien", "karnelian", "koral", "kordun", "krysztal", "kwarc", "krwawnik",
                "lazuryt", "lza", "malachit", "maronid", "nefryt", "obsydian", "oczko", "oliwin", "onyks",
